-- =====================================================================
--  BDU — The Indy Way drill library: younger-age versions
--
--  Run ONCE in the Supabase SQL Editor, after indy-drills-setup.sql:
--  https://supabase.com/dashboard/project/fpnmnlrwhwnuefbnehuf/sql
--
--  32 drills now have a separate version for a younger or less experienced
--  group, with the easier setup built into the Setup and Directions so a coach
--  of that age group can run it as written. The originals are not changed.
--   • the first 16 had a variation that named the younger group
--     ("U12/Introductory: …", "U10/Beginners: …") — that is the version
--   • the last 16 only had "Easier:" variations — their version is one age
--     group down, built from those
--  Not included: drills already at U8, and the 7v7 / 9v9 / 11v11 scrimmages
--  (the smaller scrimmage already is the younger version).
--
--   Agility Ladder (U8 Version)  ←  Agility Ladder (U8+)
--   Beep Test (U10 Version)  ←  Beep Test (U10+)
--   ¾ Mile Run (U10 Version)  ←  1 Mile Run (U10+)
--   Circular Pyramid Intervals (U10 Version)  ←  Circular Pyramid Intervals (U10+)
--   Tag-and-Release Relay (U10 Version)  ←  Tag-and-Release Relay (U10+)
--   Parallel Corridor Footwork (U8 Version)  ←  Parallel Corridor Footwork (U8+)
--   Shadow Dribbling (U8 Version)  ←  Shadow Dribbling (U8+)
--   Three-Group Continuous (U10 Version)  ←  Three-Group Continuous (U10+)
--   Target Dribbling (U10 Version)  ←  Target Dribbling (U10+)
--   Peripheral Possession with Forbidden Returns (U12 Version)  ←  Peripheral Possession with Forbidden Returns (U12+)
--   Receive, Turn & Finish (U12 Version)  ←  Receive, Turn & Finish (U12+)
--   Rock the River (U12 Version)  ←  Rock the River (U12+)
--   Lateral Shadow (U12 Version)  ←  Lateral Shadow (U12+)
--   King of the End Zones (U12 Version)  ←  King of the End Zones (U12+)
--   Around the Horn (U12 Version)  ←  Around the Horn (U12+)
--   Soccer Baseball (U10 Version)  ←  Soccer Baseball (U10+)
--   Cone Passing (U8 Version)  ←  Cone Passing (U10+)
--   10 Person Continuous (U8 Version)  ←  10 Person Continuous (U10+)
--   Gates Competition Passing (U8 Version)  ←  Gates Competition Passing (U10+)
--   Get Open (U8 Version)  ←  Get Open (U10+)
--   Gates Competition Dribbling (U8 Version)  ←  Gates Competition Dribbling (U10+)
--   Bumper Keepaway (U8 Version)  ←  Bumper Keepaway (U10+)
--   3 Team Keep Away (U8 Version)  ←  3 Team Keep Away (U10+)
--   Overload Scrimmage (U8 Version)  ←  Overload Scrimmage (U10+)
--   Attack vs. Defense (U8 Version)  ←  Attack vs. Defense (U10+)
--   Long Passes (4 People) (U10 Version)  ←  Long Passes (4 People) (U12+)
--   Across the River (U10 Version)  ←  Across the River (U12+)
--   Pierce the Circle (U10 Version)  ←  Pierce the Circle (U12+)
--   Block or One Time (U10 Version)  ←  Block or One Time (U12+)
--   Closing Fast, Shot Fast (U10 Version)  ←  Closing Fast, Shot Fast (U12+)
--   3v2 Transition (U10 Version)  ←  3v2 Transition (U12+)
--   4 Point Shooting (U12 Version)  ←  4 Point Shooting (U14+)
--
--  Each new drill sits right after its original, keeps the same video, and
--  ends its Variations with "Ready for more: …" pointing back to the original.
--  Safe to run again: a drill that already exists is left alone.
-- =====================================================================
insert into bdu_drills (id, name, icon, category, skill_level, min_age, duration, players, description,
                        setup, directions, variations, coaching_points, equipment, video_file, video_url, extra, sort_order)
values
('agility-ladder-u8', 'Agility Ladder (U8 Version)', '🏃', 'Fitness', 'Beginner', 'U8', 8, 'Any (1 ladder per 6 players)', 'Players learn three basic agility ladder patterns — single-leg run, 2-in and lateral in-and-outs — walking each one through before running it, to build foot speed and coordination.',
   array['Ladder: One agility ladder laid flat on the ground (10–12 rungs).', 'Players: Single-file line behind the start; 1 player runs at a time, jog back around the outside to rejoin the queue.', 'Spacing: Allow one player to finish before the next starts to avoid collisions.'],
   array['Walk-through: Before each pattern, every player walks it once so they know where their feet go.', 'Single-leg run: One foot in each box. 2 reps.', '2-in: Both feet in each box. 2 reps.', 'Lateral in-and-outs: Sideways down the ladder — lead foot in, trail foot in, lead foot out, trail foot out. 2 reps facing each way.', 'Jog back around the outside to rejoin the line.'],
   array['Easier: walk every rep until the pattern is clean.', 'Ready for more: add the Ickey Shuffle, then move to the full Agility Ladder.', 'Large groups (12+): Set up 2–3 ladders running simultaneously; players rotate between ladders on the coach''s signal.'],
   array['Quiet Feet: Players who slap the rungs are landing flat-footed and absorbing ground contact instead of bouncing off it — cue "light as a feather" and demonstrate the difference between heavy and quick contacts.', 'Arms Drive the Legs: Foot turnover is limited by arm swing. Pump elbows at 90 degrees cheek-to-pocket — test it by having players run arms-crossed and feel the loss of speed.', 'Progress Then Speed: Teach the pattern correctly at 50% speed first, then build to full speed — rushing a pattern before it is clean produces sloppy footwork that reinforces bad habits.'],
   array['Agility ladder', 'Cones', 'Balls (optional)'], null, null, null, 31),
('beep-test-u10', 'Beep Test (U10 Version)', '📡', 'Fitness', 'Beginner', 'U10', 15, 'Any', 'Players run 20m shuttles in time with the beep track up to Level 5 only — the goal is to learn the test and how to pace it, not to set a maximum score.',
   array['Course: Two parallel lines of cones exactly 20 meters apart on a flat, non-slip surface.', 'Audio: Load the standard 20m Multi-Stage Fitness Test (MSFT) audio on a phone or speaker. Calibrate before testing.', 'Players: All participants line up along one starting line.', 'Recording: Coach or assistant records each player''s last completed level and shuttle (e.g., "8.6" = Level 8, Shuttle 6).'],
   array['Start: All players sprint to the far line and touch it before the next beep, then sprint back on the next beep.', 'Shuttle Rule: Must reach and cross the 20m line with at least one foot before or on the beep. No early starts.', 'Warnings: First miss = warning; turn immediately and catch up. Second consecutive miss = eliminated.', 'Levels: A triple beep signals a new level — the beeps come a little quicker each time.', 'Stop: End the test after Level 5 for everyone, however fresh they look.', 'Scoring: Record the last level and shuttle each player completed (e.g. 4.3 = Level 4, Shuttle 3).'],
   array['Easier: run it once as a practice with the coach calling the turns before using the audio.', 'Ready for more: from U12, run the full Beep Test to exhaustion.', 'Mixed groups: All ages run simultaneously — slower players finish earlier and cheer teammates; no separate heat needed.'],
   array['Pacing: Level 1 feels easy — jog it. Players who sprint the early beeps are tired by Level 4.', 'Line Discipline: Touching the line before the beep (not stopping on it, not three steps past) is a learnable skill that adds 1–2 levels without any fitness gain.', 'Encouragement: Call players by name — everyone finishing Level 5 is the win.'],
   array['Cones', 'Beep test audio', 'Stopwatch', 'Score sheet'], null, null, '{"shuttleData":[{"kmh":8.5,"level":1,"shuttles":7,"secPerLap":8.47},{"kmh":9,"level":2,"shuttles":8,"secPerLap":8},{"kmh":9.5,"level":3,"shuttles":8,"secPerLap":7.58},{"kmh":10,"level":4,"shuttles":9,"secPerLap":7.2},{"kmh":10.5,"level":5,"shuttles":9,"secPerLap":6.86}]}'::jsonb, 41),
('one-mile-run-u10', '¾ Mile Run (U10 Version)', '🏃', 'Fitness', 'Beginner', 'U10', 12, 'Any', 'Players run ¾ of a mile (3 laps) — or for 10 minutes — at a steady pace, with the coach recording times to track improvement across the season.',
   array['Course: 3 laps of a 400m track = ¾ mile. On a full-size soccer field, 3 perimeter laps ≈ ¾ mile.', 'Players: All players run together. Pair faster and slower runners for pacing support.', 'Timing: Stopwatch or phone timer; record each player''s finish time individually.'],
   array['Objective: Complete 3 laps at a steady pace you can hold — or run for 10 minutes and count the laps.', 'Pacing: Coach calls out split times at each lap to help players self-regulate.', 'Finish: All players finish regardless of time — no one stops early. Coach records each time.', 'Tracking: Repeat at regular intervals (start, mid, end of season) and compare times — improvement is the goal.'],
   array['Easier: run-walk — run the long sides and walk the short sides.', 'Ready for more: from U12, run the full 1 Mile Run.', 'Mixed groups: Send faster runners 30 seconds earlier so the field stays spread out.'],
   array['Pace Awareness: Most youth players go out too hard in the first 200m — coach should remind players to slow down early; a controlled first half produces a faster overall time.', 'Breathing Rhythm: Linking breathing to stride cadence (inhale 2 strides, exhale 2 strides) keeps effort at aerobic intensity without hyperventilating — teach before the run starts.', 'Progress Tracking: Record every finish time and share personal bests each test — competing against your own previous time is more motivating than comparing with teammates.'],
   array['Stopwatch', 'Score sheet', 'Cones (optional)'], null, null, null, 51),
('circular-pyramid-intervals-u10', 'Circular Pyramid Intervals (U10 Version)', '🔄', 'Fitness', 'Beginner', 'U10', 15, '12–20 in pairs', 'Matched pairs start at evenly spaced cones around a circle and run a short pyramid together — 1, 2, 3, then back down to 2 and 1 cone-lengths — with a generous recovery pause after every rep.',
   array['Circle: Place 5 cones evenly spaced around a large circle (roughly 20–30 yd diameter).', 'Pairs: Match players by similar fitness/pace — one matched pair per cone station.', 'All pairs start simultaneously from their home cone facing the same direction around the loop.'],
   array['Rep 1: Each pair runs 1 cone length → recovery pause (45–60 sec).', 'Rep 2: Run 2 cone lengths → recovery pause.', 'Peak Rep 3: Run 3 cone lengths → longer recovery (90 sec).', 'Descend: Run 2 cone lengths, then 1, with a recovery pause after each.', 'All pairs move simultaneously; different start stations keep the circle clear of traffic.'],
   array['Easier: add 15 seconds to every recovery pause.', 'Ready for more: run the 1-5-1 pyramid — the full Circular Pyramid Intervals.', 'Large groups (16+): Use a 10-cone circle with two pairs per cone; stagger start times by 10 seconds.'],
   array['Partner Accountability: Matched pairs self-regulate pace together rather than chasing the fastest runner — improves consistency across all fitness levels.', 'Structured Recovery: Rest periods are not optional — call the rest time aloud and enforce it; shorter reps get shorter rests but longer reps need more recovery to maintain effort quality.', 'Traffic Flow: All pairs move in the same direction; remind players to return to their home cone after each rep so spacing stays consistent.'],
   array['Cones', 'Stopwatch'], null, null, null, 61),
('tag-and-release-relay-u10', 'Tag-and-Release Relay (U10 Version)', '⚡', 'Fitness', 'Beginner', 'U10', 12, '10–18 in pairs', 'Pairs at five cones around a circle sprint one cone length on a rolling "tag-and-release" trigger — when a pair arrives, the waiting pair goes — in short sets with a shared rest.',
   array['Circle: Place 5 cones evenly spaced around a large circle or track loop.', 'Pairs: One matched pair stationed at each cone facing the same direction.', 'Rest ratio: With 5 cones, each pair works about 1 turn in 5.', 'Traffic lanes: Walk everyone through it before starting — arriving runners peel outside, departing runners launch on the inside.'],
   array['1-Cone Relay: One pair sprints to the next cone; on arrival the waiting pair immediately explodes — wave rolls continuously.', 'Traffic Management: Arriving runners peel outside to recover; departing runners launch on the inside lane.', 'Duration: Run continuously for 2–3 minutes, then 2–3 minutes of active recovery. Repeat 2–3 sets.'],
   array['Easier: jog the first set so everyone learns the trigger.', 'Ready for more: 7 cones and the 2-cone leapfrog — the full Tag-and-Release Relay.', 'Large groups (16+): Run two separate relay circles simultaneously with the same start cue.'],
   array['Immediate Release: Waiting pair must explode on contact — a half-second delay breaks the wave and gives false rest; coach should call out slow releases immediately.', 'Traffic Lane Discipline: Inside-lane launches and outside-lane finishes must be drilled from rep 1 — one collision early in training can stop the session.'],
   array['Cones', 'Stopwatch'], null, null, null, 71),
('parallel-corridor-footwork-u8', 'Parallel Corridor Footwork (U8 Version)', '↔️', 'Fitness', 'Beginner', 'U8', 10, '8–14 in pairs', 'Two short parallel cone corridors — pairs work through three phases: mirror lateral shuffles, slalom weave and sole rollovers — building from pure movement into simple ball work.',
   array['Corridor: Set two parallel rows of 4 cones, 5–10 yds apart across, with cones ~2 yds apart along each row.', 'Players: Split evenly into two lines — Line A at Row 1, Line B at Row 2, partners facing each other across the channel.', 'Balls: 1 ball per player for phase 3; no ball needed for phases 1–2.'],
   array['Phase 1 — Mirror Lateral Shuffle: Both partners face each other and shuffle laterally cone-to-cone in sync, staying low with no crossover steps. 4 reps each.', 'Phase 2 — Forward Slalom Weave: Players slalom in and out of their own row of cones, emphasizing quick plant-and-push deceleration off the outside foot. 4 reps each.', 'Phase 3 — Linear Sole Rollovers: Each player has a ball and travels down the corridor using continuous sole rollovers (alternating feet), keeping hips square and ball within reach. 4 reps each.'],
   array['Easier: walk phase 3 — one rollover, stop, then the next.', 'Ready for more: add creative slalom dribbling, then move to the full Parallel Corridor Footwork.', 'Large groups (12+): Set up two corridors running simultaneously; rotate pairs between corridors between phases.'],
   array['Low Center of Gravity: All lateral movement phases require knees bent and weight on the balls of the feet — standing tall or heel-striking kills quickness and makes the shuffles sloppy.', 'Rollover Touch: In phase 3, roll the ball across with the sole and keep it within reach — small touches, hips square.'],
   array['Cones', 'Balls'], 'tactics/Lateral Movement.webm', null, null, 81),
('shadow-dribbling-u8', 'Shadow Dribbling (U8 Version)', '👥', 'Warmup', 'Beginner', 'U8', 8, 'Pairs (up to 20 players)', 'In pairs, the leader dribbles at a walk or jog around a big grid while the follower copies their path as closely as possible; roles swap on the coach''s whistle.',
   array['Grid: 20×20 yd square marked with cones — keep it big.', 'Players: Pairs spread across the grid — up to 10 pairs share a standard grid.', 'Balls: One ball per pair — the leader starts with it, the follower has none.'],
   array['The leader dribbles around the grid at a walk or jog — no sprinting — with gentle changes of direction.', 'The follower stays directly behind the leader, mirroring every movement as closely as possible without making contact.', 'If the follower falls more than 3 yards behind, the leader slows down until the gap closes.', 'On the coach''s whistle, the leader stops, passes the ball to the follower, and roles reverse immediately.', 'Run 3–5 rounds of 45–60 seconds each.'],
   array['Easier: play follow-the-leader at a walk with no ball first.', 'Ready for more: allow full speed and sudden turns — the full Shadow Dribbling.', 'Large groups (12+): Give both partners a ball — leader and follower dribble simultaneously while maintaining their relative positions.'],
   array['Body Orientation: The follower should be reading the leader''s hips and shoulders — not the ball — to anticipate direction changes before they happen.', 'Close Control: Leaders should use all surfaces of the foot (inside, outside, sole) to keep the ball tight at high speed, making it harder to predict the next move.', 'Spatial Awareness: Both players must be aware of other pairs in the grid at all times — heads up is mandatory for safe play.'],
   array['Balls', 'Cones'], null, null, null, 91),
('three-group-continuous-u10', 'Three-Group Continuous (U10 Version)', '🔄', 'Technical', 'Beginner', 'U10', 15, '12–18 in 3 groups', 'Three groups rotate through a hub-and-rim circuit on the ground only: central runners check out of the hub to an outer station, receive a pass, play it two-touch to the station partner, then reset through the hub to the next open station.',
   array['Hub: Mark a center circle using cones or pinnies (~10 yd diameter).', 'Rim: Place 4 cones evenly spaced around the outside of the hub, each ~5–8 yds from the center.', 'Players: Three equal groups. Group 1 starts in the center hub without balls. Groups 2 & 3 pair up at the outer cone stations — one player 3 feet left of the cone, one 3 feet right.', 'Balls: One ball per station pair — the left-side player starts with the ball.'],
   array['Check & Call: A central player checks out of the hub toward a free station, makes eye contact, and calls for the ball.', 'Give-and-Go: The station player passes on the ground to the central player, who plays it two-touch to the station partner.', 'Reset: The central player checks back through the hub, scans, and explodes to the next available station.', 'Rotation: Each 60-second round, the group in the hub is the working group. After the round, groups rotate — every group works the center once per skill set.', 'Skill: Two-touch on the ground for every rotation. Move to one-touch only when the rotation runs without stopping.'],
   array['Easier: walk one full rotation so everyone learns where to go.', 'Ready for more: add the aerial progressions — the full Three-Group Continuous.', 'Large groups (15+): Add a 4th or 5th outer station; keep the same rotation structure.'],
   array['Vocal & Physical Check: Central players must check at game speed with arms up and call the server''s name before the pass is made — silent or slow checks do not replicate game conditions.', 'Open Body Shape: Arrive at the station with hips angled to see the server, the partner, and the center field simultaneously — arriving square limits vision and slows distribution.', 'Scanning in the Hub: Players must lift their heads before they arrive in the center, not after — early scanning allows them to accelerate directly toward the next free station rather than stopping to look.'],
   array['Balls', 'Cones', 'Pinnies'], '10 Person Continuous - 3 way.webm', null, null, 141),
('target-dribbling-u10', 'Target Dribbling (U10 Version)', '🎯', 'Dribbling', 'Beginner', 'U10', 12, '6–8 per grid', 'Each player dribbles freely inside a grid for 60 seconds with no defenders, scoring points by rolling the ball over flat pinnies — 3 for the yellow in the center, 1 for the reds around the edge.',
   array['Grid: 20×20 yd square marked with cones (adjust size based on player count).', 'Center target: Place 1 yellow pinnie flat in the center of the grid (3 points).', 'Perimeter targets: Place 4–6 red pinnies flat around the edges and corners of the grid (1 point each).', 'Players: Everyone has a ball and plays for themselves — no defenders.'],
   array['Objective: Dribble your ball directly over a target pinnie to score — the ball must roll cleanly over the flat pinnie, not past it.', 'Scoring: Yellow center penny = 3 points. Red perimeter penny = 1 point.', 'No-Repeat Rule: A player cannot score on the same penny back-to-back — after hitting the center yellow, they must score on a red perimeter penny before attacking the middle again.', 'Rounds: Play 60-second rounds with 30 sec rest. Each player counts their own points and tries to beat their score next round.'],
   array['Easier: drop the no-repeat rule.', 'Ready for more: add defenders — the full Target Dribbling game.', 'Large groups (12+): Split into two grids running simultaneously; winners from each grid compete in a final round.'],
   array['Scanning: Lift your head between touches and find the next open pinnie before you get there.', 'Close Ball Control: Rolling the ball precisely over a flat pinnie demands tight, controlled touches; players quickly learn that overrunning the ball or using big touches causes them to miss the target and lose possession.'],
   array['Balls', 'Cones', 'Pinnies (yellow and red)'], 'Target Dribbling.webm', null, null, 191),
('peripheral-possession-u12', 'Peripheral Possession with Forbidden Returns (U12 Version)', '🔵', 'Possession', 'Intermediate', 'U12', 20, '11–15', 'Perimeter players keep possession around the outside of a rectangle against 3 central defenders with one restriction: no passing to the adjacent teammate on the same touchline.',
   array['Grid: 20×25 to 25×30 yard rectangle.', 'Players: 3 evenly spaced cones per touchline; up to 12 perimeter players (scale to 8 for smaller groups). 3 defenders inside.', 'Perimeter players stand one step outside the boundary and cannot enter the grid.'],
   array['Objective: Keep possession around the outside against 3 interior defenders.', 'No Same-Line Passes: Cannot pass to the immediate neighbor on the same touchline — ball must travel to another side.', 'Defender Freedom: Defenders can break outside the grid to tackle on a heavy touch.', 'Swap Rule: Player who makes an error swaps into the grid as a defender.'],
   array['Easier: play against 2 defenders.', 'Ready for more: add the no-bounce-back rule — the full Peripheral Possession with Forbidden Returns.', 'Small Groups (8 players): Use a 15×20 yard grid with 2 cones and 1 player per bay.'],
   array['Pre-Orientation & Scanning: Eyes must find cross-grid options before the ball arrives — there is no easy neighbor pass.', 'Positive First Touch: Directional touch across the body opens a clean passing lane and keeps defenders from lunging over the boundary.', 'Defensive Triggers: Defenders learn to read body posture and press aggressively when a perimeter player takes a trapped touch near the boundary.'],
   array['Balls', 'Cones', 'Pinnies'], 'tactics/Peripheral Possession with Forbidden Returns.webm', null, null, 231),
('receive-turn-finish-u12', 'Receive, Turn & Finish (U12 Version)', '🥅', 'Shooting', 'Beginner', 'U12', 15, '6–12', 'Two lines run toward timing cones where the coach rolls in an easy ground pass; each player opens toward their goal with the first touch, may take one more to set the ball, and finishes.',
   array['Goals: Two goals set side-by-side or angled outward on the end line (full-size, intermediate, or pug goals — with or without keepers).', 'Players: Two lines at a starting cone near midfield or top of the center circle.', 'Timing cones: A second cone ~10–15 yards ahead of each line, roughly 20–25 yards from the respective goal.', 'Server: Coach positioned near the goals with a supply of balls, serving ground passes to each line in alternation.'],
   array['The Run: A player from one line sprints forward toward their timing cone.', 'The Delivery: The coach serves a gentle ground pass timed to arrive as the player reaches the timing cone.', 'The Touch & Turn: Left-line players open hips toward the left goal with a back-foot touch for a left-footed finish; right-line players do the same toward the right goal.', 'The Finish: Take an extra touch to set the ball if needed, then strike on target.', 'Rotation: Players rotate to the back of the opposite line so every player gets reps finishing with both feet.'],
   array['Easier: start with a still ball at the timing cone.', 'Ready for more: a full-speed serve and 2 touches maximum — the full Receive, Turn & Finish.', 'Large groups (12+): Run both lines simultaneously — left and right players go at the same time to keep rep rate high.'],
   array['Weight of the Touch: A positive, forward-angled first touch sets up the shot — a dead stop kills momentum and allows the keeper to set.', 'Timing the Run: Players who arrive at the timing cone too fast are off-balance on the receive; a slight deceleration before the cone keeps hips and shoulders through the ball.', 'Hips & Plant Foot: The plant foot must point at the target corner — a misaligned plant sends the shot across the body and wide.'],
   array['Balls', 'Cones', '2 goals (full-size or pug)'], 'Charge Touch Shoot.mp4', null, null, 281),
('rock-the-river-u12', 'Rock the River (U12 Version)', '🌊', 'Tactical', 'Intermediate', 'U12', 20, '10–12', 'Two teams each occupy a possession grid separated by a narrow river with a few scattered balls ("rocks"); the team without the ball sends 2 defenders across to press, and when they win it they get it back over the river to their teammates with a chip or a low driven pass around the rocks.',
   array['Grids: Two equal boxes (15×15 to 20×20 yds), placed side by side with a 3–4 yd river channel running between them.', 'River: Scatter 4–6 spare balls across the river channel floor as "rocks."', 'Players: Two equal teams of 5–6 players — each team starts in their home grid.'],
   array['Possession: Coach serves the match ball into Team A''s grid. Team A plays keep-away; Team B sends 2 defenders across the river to press.', 'Reinforcement: If the pressing pair cannot win the ball within a set time (e.g. 8 passes by Team A), they may call for a 3rd defender to cross the river.', 'Transition: When defenders win the ball, they play it across the river to their teammates — a chip, or a low driven pass that rolls to the side of the rocks.', 'Role flip: Once Team B receives in their grid, they play keep-away and Team A sends 2 defenders across.', 'Out-of-bounds scramble: If the ball exits, the river goes live — any player may sprint in to claim a rock. The team that grabs one becomes the possession team; coach adjudicates ties.'],
   array['Easier: take the rocks out for the first round.', 'Ready for more: widen the river and require a true chip — the full Rock the River.', 'Large groups (14+): Split into two simultaneous games with separate rivers; rotate teams every 5 minutes.'],
   array['Getting It Across: Pick the gap between the rocks and strike firmly through the middle of the ball; try the chip when there is time.', 'Pressing Pair Organization: Two defenders must work as a unit — trap toward a corner, cut the pass back, and resist both chasing the ball blindly; call for the 3rd only when the ball is truly pinned.', 'First Touch Out of the Air: Receivers must read the flight early, position their body before contact, and cushion the ball into open space on the first touch to absorb immediate pressure.'],
   array['Balls (many)', 'Cones', 'Pinnies'], 'tactics/Rock the River.webm', null, null, 301),
('lateral-shadow-u12', 'Lateral Shadow (U12 Version)', '⚡', 'Tactical', 'Intermediate', 'U12', 15, '6–12', 'The defender plays a ground pass to the attacker ~30 yards out, then sprints to close — slowing into a side-on jockey stance 2 yards away and shadowing the attacker wide. No goalkeeper: the whole focus is the approach and the stance.',
   array['Field: 18-yard box area with a standard goal — no goalkeeper.', 'Defender line: Positioned centrally or slightly staggered, 3–5 yards beyond the top of the 18, each player holding a ball.', 'Attacker line: Stationed at a cone ~10–12 yards further upfield (roughly 30–35 yards from goal), facing the defender.'],
   array['Service: The defender plays a firm ground pass to the feet of the attacker and immediately sprints to close.', 'Breakdown: Around 2–3 yards from the attacker, the defender drops their hips, chops strides, and assumes a side-on jockey stance.', 'Shadow & Steer: The defender shadows the attacker laterally — matching their rhythm and body feints — while opening their body to offer the outside/weak-foot lane and blocking the central route to goal.', 'Pounce: The defender waits for a heavy touch, hesitation, or head-down dribble before attempting a block or poke tackle. The rep ends when the defender wins it, the attacker gets a shot away, or after 8 seconds.', 'Rotation: Attacker retrieves their ball and joins the defender line; defender rotates to the attacker line.'],
   array['Easier: the attacker dribbles at half speed so the defender can find the stance.', 'Ready for more: add a goalkeeper for a live shot — the full Lateral Shadow.', 'Large groups (12+): Run two parallel lines simultaneously; coach calls "go" to both pairs at once to increase rep rate.'],
   array['Fast Approach, Slow Arrival: Sprint while the ball is traveling to close distance quickly, but decelerate sharply 2 yards from the attacker — a flat-out arrival means the attacker can knock it past and run.', 'Surfer Stance: Hips angled ~45 degrees, knees bent, weight on the balls of the feet — this allows instant lateral push-off in either direction. Never stand chest-square or flat-footed.', 'Patience Over Heroics: The defender''s job is not to win the ball in the first two seconds — it is to deny a good shot. A hurried attempt from a wide angle is a defensive win.'],
   array['Balls', 'Cones', 'Pinnies', 'Full-size goal'], 'Lateral Shadow.webm', null, null, 311),
('king-of-the-end-zones-u12', 'King of the End Zones (U12 Version)', '👑', 'Tactical', 'Intermediate', 'U12', 20, '12 in 4 teams', 'Four teams of three compete with a central grid and an end zone at each end — two teams play 3v3 in the middle with two touches while one waits in each end zone; the team that plays a pass into their target end zone swaps with the team waiting there.',
   array['Grid: Central playing area ~25×20 yds with an end zone (5–8 yds deep) at each end.', 'Players: 4 equal teams of 3 players in distinct colored pinnies (Red, Blue, Yellow, Green).', 'Starting positions: Two teams in the central grid (e.g. Red vs. Blue); one team in each end zone (Yellow north, Green south).'],
   array['Objective: The two teams in the middle each attack the opposite end zone — Red attacks south, Blue attacks north.', 'Two-Touch: Every player has a maximum of 2 touches.', 'Scoring / Swap: A team scores by completing a controlled pass into their target end zone. The scoring team enters that end zone; the waiting team sprints into the grid and attacks in the opposite direction.', 'Turnover Rule: If possession is lost, the defending team takes over immediately. Coach can feed a fresh ball to the team that wins possession.', 'Out of Bounds: Opposing team restarts with a kick-in, or coach feeds a fresh ball to maintain tempo.', 'Game Length: Play continuously for 10–15 minutes, or first team to 5 swaps wins.'],
   array['Easier: allow 3 touches.', 'Ready for more: 4v4 with no touch limit — the full King of the End Zones.', 'Large groups (20+): Run two grids simultaneously; top team from each grid meets in a challenge round.'],
   array['Vertical Penetration: The end zones reward teams that look forward first — players must scan and play the vertical pass as soon as it opens rather than recycling sideways.', 'Instant Transition: The moment a swap happens, the incoming team must shift from passive waiting to full-speed attack in the opposite direction — that disorganization window is where possession is lost.', 'Defensive Pressure: Press immediately after a swap — the new attacking team is temporarily disorganized, and that is the window to win the ball back.'],
   array['Balls', 'Cones', 'Pinnies (4 colors)'], 'King of the End Zones.mp4', null, null, 321),
('around-the-horn-u12', 'Around the Horn (U12 Version)', '↔️', 'Tactical', 'Intermediate', 'U12', 20, '14–22 including 2 goalkeepers', 'Two teams defend side-by-side goals on the end line, separated by a short cone spine the ball cannot cross — possession must loop around the far tip of the cones to switch flanks and attack. Played with three touches to slow the tempo.',
   array['Goals: Two full-size or intermediate goals side-by-side on the end line, each with a goalkeeper.', 'Spine: A line of cones runs from between the goals straight down the center of the pitch to just past the 18-yard box.', 'Players: Two equal teams (7v7 to 11v11) — each team defends one goal.'],
   array['The Ball Rule: The ball may NOT cross or pass through the cone spine — teams must circulate around the far tip of the cones to switch flanks.', 'The Player Rule: Attacking and defending players CAN cross the spine freely at any time — use this for blind-side overlaps, crosses, and defensive recovery.', 'Three-Touch: Every player has a maximum of 3 touches.', 'Scoring: A team scores by finishing past the opposing goalkeeper in their assigned goal.', 'Turnovers: If the ball crosses the spine, possession transfers immediately to the opposing team at the point of infringement.', 'Game Length: Play in 8–10 minute periods, or first to 5 goals.'],
   array['Easier: allow 4 touches.', 'Ready for more: run the spine to midfield with no touch limit — the full Around the Horn.', 'Small groups (6v6 or fewer): Use smaller intermediate goals and shorten the spine to two-thirds field.'],
   array['Width Before Penetration: The spine forces the ball wide, teaching players to build in the channels and create crossing opportunities before attempting to score.', 'Blind-Side Timing: Because the ball must travel the long route, central runners have time to check defenders, cross the spine, and arrive in the box from an unexpected angle — cross late, arrive fast.', 'Defensive Shape: Defenders must actively shift from one side of the spine to the other as the attack changes flanks — static defenders will be pulled apart by the wide circulation.'],
   array['Balls', 'Cones', 'Pinnies (2 colors)', '2 full-size goals'], 'The Spine.mp4', null, null, 331),
('soccer-baseball-u10', 'Soccer Baseball (U10 Version)', '🏟️', 'Games', 'Beginner', 'U10', 15, '10–20 plus a goalkeeper', 'Two teams compete at once — one sprints a relay around a short loop like baseball bases while the other shoots from a close cone; every goal scored before the last runner finishes counts as a run. One inning: each team runs once and shoots once.',
   array['Diamond: A short loop of 4 cones in front of goal — about 20 yds wide and 10 yds deep — instead of the full 18-yard box. Home is at one goalpost; 1st, 2nd and 3rd are the other corners.', 'Teams: Two equal groups — one is the Running Team, one is the Shooting Team.', 'Shooting line: A cone 8–10 yards from goal.'],
   array['Relay: Runner 1 sprints the full loop (Home → 1st → 2nd → 3rd → Home). The next runner starts when the teammate ahead rounds 3rd base.', 'Shooting: While the runners are going, the shooting team takes shots one after another from the cone. Shooters collect their own ball and rejoin the line.', 'Scoring: Every goal the shooting team scores before the final runner crosses Home = 1 Run.', 'Inning: Once all runners have finished, teams swap roles. Play 1 full inning — the team with the most runs wins.'],
   array['Easier: play without a goalkeeper.', 'Ready for more: 3 innings around the full 18 from the penalty spot — the full Soccer Baseball.', 'Large groups (16+): Run two shooting queues simultaneously to maximize rep rate and maintain pressure on runners.'],
   array['Conditioning Disguised as Competition: Runners sprint at 100% because the other team is scoring — this converts a fitness drill into a competitive game without a single "run a lap" command.', 'Composure Under Pressure: Shooters feel urgency from the runners'' pace, which mirrors in-game pressure — the coaching win is players who stop blasting and start placing shots.', 'Tempo Management: The drill lives or dies by pace — keep spare balls at the shooting line and loudly push shooters to reload and fire; any lull deflates the competitive tension.'],
   array['Balls (many)', 'Cones', 'Full-size goal'], 'tactics/baseball.webm', null, null, 401),
('cone-passing-u8', 'Cone Passing (U8 Version)', '🎯', 'Technical', 'Beginner', 'U8', 12, '6–12 in 2 groups', 'Two color groups pass to the other color across a field of cones — two touches, then move to an open cone.',
   array['Cones spread across a 30×30 yd area — more cones than players', 'Two groups in different colors (e.g. red and blue)', 'One ball for every 2–3 players', 'Every player starts at a cone'],
   array['Red passes to blue, blue passes to red.', 'The player with the ball takes two touches — one to control, one to pass — to a player of the other color.', 'After passing, the passer runs to an open cone.', 'Sets last 2 minutes with 1 minute of rest. Run 4 sets.', 'Change the pass each set: inside of the right foot, inside of the left foot, then free choice.'],
   array['Easier: fewer balls, and players may stop the ball with the sole first.', 'Harder: call the receiver''s name before passing.', 'Ready for more: add a skill before each pass and a third color — the full Cone Passing.'],
   array['Control first, then pass — don''t rush the touch', 'Move immediately after passing', 'Find a player of the other color before the ball arrives'],
   array['Balls', 'Cones (many)', 'Pinnies (2 colors)'], 'cone passing.mp4', null, null, 121),
('movement-skill-reset-u8', '10 Person Continuous (U8 Version)', '🔄', 'Technical', 'Beginner', 'U8', 12, 'About 10', 'Continuous run-receive-return work on the ground: run through the gate, call for the ball, pass it back in two touches and go again.',
   array['A cone gate 2–3 yds wide in the middle of a 15×15 yd area', 'Half the group spread around the outside, each with a ball', 'The other half work in the middle without a ball'],
   array['A working player runs through the gate and calls an outside teammate''s name to receive a pass.', 'The outside player passes the ball along the ground.', 'The working player controls it and passes it back — two touches.', 'They run through the gate again and find a different server.', 'Run each round for 1 minute, then swap the groups.', 'Change one thing each round: right foot only, left foot only, then one-touch if they are ready.'],
   array['Easier: working players walk through the gate for the first round.', 'Harder: one-touch returns.', 'Ready for more: add volleys, headers and traps from a served ball — the full 10 Person Continuous.'],
   array['Eye contact before the pass — use their name', 'First touch must be out of your feet', 'Receive, play, reset — stay alert'],
   array['Balls', 'Cones'], 'MovementSkillResetFindTarget.mp4', null, null, 131),
('gates-competition-passing-u8', 'Gates Competition Passing (U8 Version)', '🚪', 'Passing', 'Beginner', 'U8', 10, 'Pairs', 'Pairs pass to each other through wide cone gates, counting how many they can score in 45 seconds and trying to beat their own best.',
