   array['Easier: the defender stands still on the cone with arms out.', 'Harder: the defender can jog.', 'Ready for more: a full-speed defender who swaps out when they win it — the full Get Open.'],
   array['Change direction with purpose — don''t just run sideways', 'Use a shoulder drop or change of pace to create separation', 'Passer: wait for the right moment — don''t force the pass'],
   array['Balls', 'Cones'], 'get open.mp4', null, null, 171),
