   array['Balls', 'Cones', 'Pinnies (2 colors)'], 'tactics/Pierce the Circle.webm', null, null, 241),
('block-or-one-time-u10', 'Block or One Time (U10 Version)', '🥅', 'Shooting', 'Beginner', 'U10', 15, '9–15 in 3 teams', 'Three-team finishing game: strikers get two touches to shoot while the blocking team waits at the post, then comes out to get in the way.',
